import{_ as t,a as r,b as a,c as o}from"./chunks/blend-modes.AsLE9LMZ.js";import{_ as s,o as n,c as i,a2 as l}from"./chunks/framework.Bzj1XTnB.js";const f=JSON.parse('{"title":"Layers","description":"Keep backgrounds, characters and effects apart, and use opacity, blending, clipping masks and glow.","frontmatter":{"lang":"en","slug":"layers","order":6,"title":"Layers","description":"Keep backgrounds, characters and effects apart, and use opacity, blending, clipping masks and glow."},"headers":[],"relativePath":"layers.md","filePath":"layers.md"}'),g={name:"layers.md"};function p(h,e,d,c,y,u){return n(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h1><p>Layers are like clear sheets stacked on top of each other. Put the background on one, a character on another, and you can redraw the character without touching the background. A project can have up to <strong>15 layers</strong>.</p><p>Tap <strong>Layer</strong> in the bottom bar.</p><p><img src="'+t+'" alt="Layers"></p><ul><li>The layer at the <strong>top</strong> of the list is drawn on top.</li><li><strong>Tap</strong> a layer to draw on it. Tap the selected layer&#39;s name to rename it.</li><li><strong>≡ handle</strong> — drag to change the order (or long-press the row and drag).</li><li><strong>👁 eye</strong> — hide or show the layer.</li><li><strong>Pink +</strong> — add a new layer.</li><li><strong>›</strong> — the layer&#39;s settings.</li></ul><p><strong>Swipe a layer to the left</strong> for <strong>Lock</strong> (stops any drawing on it), <strong>Merge</strong> (joins it with the layer below), <strong>Duplicate</strong> and <strong>Delete</strong>.</p><p><img src="'+r+'" alt="Layer actions"></p><h2 id="layer-settings" tabindex="-1">Layer settings <a class="header-anchor" href="#layer-settings" aria-label="Permalink to &quot;Layer settings&quot;">​</a></h2><p><img src="'+a+'" alt="Layer settings"></p><ul><li><p><strong>Name</strong> and <strong>Opacity</strong>.</p></li><li><p><strong>Blending mode</strong> — how the layer mixes with the ones below: Normal, Multiply (great for shadows), Screen (light), Overlay, Darken, Lighten, Add, Color Dodge, Color Burn, Hard Light, Soft Light, Difference, Exclusion, Hue, Saturation, Color and Luminosity.</p><p><img src="'+o+'" alt="Blending modes"></p></li><li><p><strong>Alpha lock</strong> — paint only over what is already drawn on this layer. Perfect for shading inside the lines.</p></li><li><p><strong>Clipping mask</strong> — show this layer only where the layer below has drawing. Put a pattern or shadow layer above a character and clip it.</p></li><li><p><strong>Pixel effect</strong> — turns the layer into chunky pixels (choose the pixel size).</p></li><li><p><strong>Glow</strong> — a soft glow around the drawing, with its own colour, size and strength.</p></li><li><p><strong>Merge down</strong> — joins this layer with the one below. <strong>Undo</strong> brings both back. <strong>Duplicate</strong> and <strong>Delete</strong> are here too.</p></li></ul><p>Deleting a layer removes it from <strong>every</strong> frame.</p>',11)])])}const _=s(g,[["render",p]]);export{f as __pageData,_ as default};
